def solution(all_characters):
    """
    Given three strings s1, s2, and virus (each on a separate line),
    find the longest common subsequence of s1 and s2 that does not contain
    virus as a substring.

    All inputs are passed together as a single string with newlines.
    """
    lines = all_characters.strip().split('\n')
    if len(lines) < 3:
        return "0"

    s1 = lines[0].strip()
    s2 = lines[1].strip()
    virus = lines[2].strip()

    n, m, v = len(s1), len(s2), len(virus)

    if n == 0 or m == 0:
        return "0"

    # KMP preprocessing for virus
    pi = [0] * v
    for i in range(1, v):
        j = pi[i - 1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j - 1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # KMP state transition table: given state and char, result next state
    trans = [[0] * 26 for _ in range(v + 1)]
    for state in range(v + 1):
        for char_code in range(26):
            c = chr(ord('A') + char_code)
            if state == 0 or c == virus[state]:
                trans[state][char_code] = state + 1
            else:
                j = state
                while j > 0 and virus[j] != c:
                    j = pi[j - 1]
                if virus[j] == c:
                    trans[state][char_code] = j + 1
                else:
                    trans[state][char_code] = 0

    # DP: dp[i][j][state] = length of LCS using s1[:i], s2[:j], virus-state
    dp = [[[0] * (v + 1) for _ in range(m + 1)] for __ in range(n + 1)]
    parent = [[[None] * (v + 1) for _ in range(m + 1)] for __ in range(n + 1)]

    # Track valid states: any state that is NOT the full virus (state == v)
    full_valid = v >= v  # This is true if the virus itself is empty
    if full_valid:
        return "0"

    for i in range(n + 1):
        for j in range(m + 1):
            for state in range(v):
                # Skip if this state allows the full virus
                if state == v:
                    continue

                dp[i][j][state] = 0
                parent[i][j][state] = None

    # Fill DP table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            char1 = ord(s1[i - 1]) - ord('A')
            char2 = ord(s2[j - 1]) - ord('A')

            # Match characters
            if s1[i - 1] == s2[j - 1]:
                for state in range(v):
                    new_state = trans[state][char1]
                    if new_state != v:  # Valid, doesn't complete virus
                        if dp[i][j][new_state] < dp[i-1][j-1][state] + 1:
                            dp[i][j][new_state] = dp[i-1][j-1][state] + 1
                            parent[i][j][new_state] = (i-1, j-1, state)

            # Skip s1 character
            for state in range(v):
                new_state = trans[state][char1]
                if new_state != v:
                    if dp[i][j][new_state] < dp[i-1][j][state]:
                        dp[i][j][new_state] = dp[i-1][j][state]
                        parent[i][j][new_state] = (i-1, j, state)

            # Skip s2 character
            for state in range(v):
                new_state = trans[state][char2]
                if new_state != v:
                    if dp[i][j][new_state] < dp[i][j-1][state]:
                        dp[i][j][new_state] = dp[i][j-1][state]
                        parent[i][j][new_state] = (i, j-1, state)

    # Find max length among all valid states at (n, m)
    max_len = 0
    best_state = -1
    for state in range(v):
        if dp[n][m][state] > max_len:
            max_len = dp[n][m][state]
            best_state = state

    if max_len == 0:
        return "0"

    # Reconstruct the LCS by backtracking
    res = []
    i, j, state = n, m, best_state
    while i > 0 and j > 0 and state != -1:
        par = parent[i][j][state]
        if par is None:
            break
        pi_, pj_, gest = par
        if (i - 1, j - 1, gest) == par:
            # We must have picked s1[i-1] == s2[j-1]
            if s1[i - 1] == s2[j - 1]:
                res.append(s1[i - 1])

        i, j, state = pi_, pj_, gest

    res.reverse()
    return ''.join(res)

