    # city i -> T with capacity b[i]
    for i in range(n):
        dinic.add_edge(i, T, b[i])

    # city i -> city j with infinity capacity
    INF = float('inf')
    for i in range(n):
        for j in range(n):
            if adj[i][j]:
                dinic.add_edge(i, j, INF)

    # Compute max flow
    max_flow = dinic.max_flow(S, T)

    if max_flow != sum_a:
        return "NO"

    # Reconstruct solution
    # flow_in[j][i] = soldiers from city i going to city j
    flow_in = [[0] * n for _ in range(n)]

    # Track flows on city-to-city edges
    INF_val = 10**9 + 7

