def derangement(n, mod):
    """Compute the number of derangements D(n) modulo mod."""
    if n == 0:
        return 1
    if n == 1:
        return 0

    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 0

    for i in range(2, n + 1):
        dp[i] = (i - 1) * (dp[i - 1] + dp[i - 2])
        dp[i] %= mod

    return dp[n]

