    # Count leaves in subtree for a given node index
    def count_leaves(idx):
        node = tree[idx]
        if node['type'] == 'leaf':
            return 1
        return count_leaves(node['left']) + count_leaves(node['right'])

    # Solve using recursion
    # Returns the value that will be at this subtree's root
    def solve(idx):
        node = tree[idx]

        # Base case: leaf node
        if node['type'] == 'leaf':
            return node['value']

        # Recursively solve for both children
        left_val = solve(node['left'])
        right_val = solve(node['right'])

        # Count leaves in both subtrees
        left_leaves = count_leaves(node['left'])
        right_leaves = count_leaves(node['right'])

        # Total moves needed below this node to reduce both subtrees
        moves_below = (left_leaves - 1) + (right_leaves - 1)

        # If moves_below is even, Pieguy made the last move above this node,
        # so Pieguy gets to choose (maximize) at this node
        # If moves_below is odd, Piegirl got the last move, so minimizes
        if moves_below % 2 == 0:
            # Pieguy's turn to decide - maximize
            return max(left_val, right_val)
        else:
            # Piegirl's turn to decide - minimize
            return min(left_val, right_val)

    return solve(root)

