def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    edges = []
    for line in lines[1:]:
        if not line.strip():
            continue
        a, b = map(int, line.split())
        edges.append((a, b))

    adj = defaultdict(list)
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    all_nodes = set(adj.keys())
    results = []

    def is_valid_complete_depth(new_adj, all_nodes_set):
        """Check if all nodes reachable from any root have consistent depth pattern"""
        if not new_adj:
            return True
        if len(new_adj) == 1:
            return True

        # Try each node as potential starting point (root after removal)
        for root in all_nodes_set:
            if root not in new_adj or not new_adj[root]:
                continue

            visited = {}
            queue = deque([(root, 0)])
            visited[root] = 0

            depths = set()
            while queue:
                node, depth = queue.popleft()
                depths.add(depth)

                for neighbor in new_adj[node]:
                    if neighbor not in visited:
                        visited[neighbor] = depth + 1
                        queue.append((neighbor, depth + 1))

            if len(visited) != len(all_nodes_set):
                continue

            # For complete full binary tree minus one node,
            # max depth should be n-1 (or n-2) and must be contiguous
            max_depth = max(depths)
            if max_depth >= n:
                continue

            # In original, depths go 0, 1, 2, ..., n-1
            # After removal, some depths might be missing but range should be small
            if any(d not in depths for d in range(max_depth + 1)):
                continue

            return True

        return False

    for candidate in all_nodes:
        new_adj = defaultdict(list)

        candidates_children = []
        found_parent = None

        if candidate in adj:
            candidates_children = list(adj[candidate])

            # Find parent: node with exactly 1 edge to candidate
            for nbr in candidates_children:
                cnt = sum(1 for c in adj[nbr] if c == candidate)
                if cnt == 1:
                    found_parent = nbr

        if found_parent is None:
            continue

        # Rewire: connect parent to all children
        for child in candidates_children:
            new_adj[found_parent].append(child)
            new_adj[child].append(found_parent)

        # Add remaining edges (copy from original excluding candidate)
        for node in all_nodes:
            if node == candidate:
                continue
            new_adj[node] = []
            for neighbor in adj[node]:
                if neighbor != candidate:
                    new_adj[node].append(neighbor)
                    new_adj[neighbor].append(node)

        if is_valid_complete_depth(new_adj, all_nodes):
            results.append(found_parent)

    results.sort()

    output = str(len(results))
    if results:
        output += '\n' + ' '.join(map(str, results)) + '\n'
    else:
        output += '\n'

    return output

