def solution(input_str):
    """
    Count numbers in [l, r] that are both:
    1. Prime (Peter's lucky numbers)
    2. Expressible as a² + b² with a,b > 0 (Bob's lucky numbers)

    By Fermat's theorem on sums of two squares, a prime p can be written as 
    a² + b² iff p = 2 or p ≡ 1 (mod 4).
    """
    input_str = input_str.strip()
    if not input_str:
        return '0\n'

    try:
        l, r = map(int, input_str.split())
    except:
        return '0\n'

    if r < 2:
        return '0\n'

    if l < 2:
        l = 2

    if l > r:
        return '0\n'

    size = r - l + 1
    is_composite = [False] * size

    sqrt_r = int(r**0.5) + 1

    is_prime_base = [True] * (sqrt_r + 1)
    if sqrt_r >= 0:
        is_prime_base[0] = False
    if sqrt_r >= 1:
        is_prime_base[1] = False

    max_base = int(sqrt_r**0.5) + 1
    for p in range(2, max_base):
        if is_prime_base[p]:
            for j in range(p*p, sqrt_r + 1, p):
                is_prime_base[j] = False

    base_primes = [p for p in range(2, sqrt_r + 1) if is_prime_base[p]]

    for p in base_primes:
        start = max(p * p, ((l + p - 1) // p) * p)
        for num in range(start, r + 1, p):
            is_composite[num - l] = True

    count = 0
    for i in range(size):
        num = l + i
        if not is_composite[i]:
            if num == 2 or num % 4 == 1:
                count += 1

    return str(count) + '\n'

