    offers = defaultdict(list)
    for i in range(2, 2 + m):
        d, t = list(map(int, lines[i].split()))
        t -= 1  # convert to 0-indexed
        offers[t].append(d)

    # Sort sale days for each type
    for i in offers:
        offers[i].sort()

    total_items = sum(k)
    left, right = 1, max(1, total_items * 2)
    result = right

    def check(X):
        # Calculate minimum cost to buy all items by day X
        total_cost = 0

        for i in range(n):
            if k[i] == 0:
                continue

            sale_days = offers[i]

            # Check if there's at least one sale day <= X
            if sale_days:
                has_sale = False
                for d in sale_days:
                    if d <= X:
                        has_sale = True
                        break

                if has_sale:
                    # Buy all k[i] items at 1 burle each (on sale)
                    total_cost += k[i]
                else:
                    # Must buy at 2 burles each
                    total_cost += k[i] * 2
            else:
                # No sale ever, must buy at 2 burles each
                total_cost += k[i] * 2

            # Early exit if cost exceeds X
            if total_cost > X:
                return False

        return True

    # Binary search for minimum X
    while left <= right:
        mid = (left + right) // 2
        if check(mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return str(result) + '\n'

