        loser_threshold = 24 if set_type <= 4 else 14

        winner_pts, loser_pts = (a_pts, b_pts) if a_pts > b_pts else (b_pts, a_pts)

        if winner_pts < threshold:
            return False
        if loser_pts > loser_threshold:
            return False
        if loser_pts == loser_threshold and (winner_pts - loser_pts < 2):
            return False

        return True

