    # Cache for memoization
    memo = {}

    def min_steps(current):
        if current == 0:
            return 0
        if current in memo:
            return memo[current]

        digits = set()
        temp = current
        while temp > 0:
            digit = temp % 10
            digits.add(digit)
            temp //= 10

        best = float('inf')
        for d in digits:
            if d > 0:
                result = min_steps(current - d)
                best = min(best, result + 1)

        memo[current] = best
        return best

    result = min_steps(n)
    return str(result) + "\n"

