    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    s = lines[1]
    OFFSET = k
    MAX_OFFSET = 2 * k + 1

    # reach[i][offset] indicates if balance is reachable at position i
    # offset maps to balance via: balance = offset - OFFSET
    reach = [[False] * MAX_OFFSET for _ in range(n + 1)]

    # parent[i][offset] stores (prev_offset, action) for reconstruction
    parent = [[None] * MAX_OFFSET for _ in range(n + 1)]

    reach[0][OFFSET] = True

    for i in range(n):
        for prev_offset in range(MAX_OFFSET):
            if not reach[i][prev_offset]:
                continue

            balance = prev_offset - OFFSET
            char = s[i]

            if char == '?':
                actions = ['W', 'L', 'D']
            else:
                actions = [char]

            for action in actions:
                new_balance = balance
                if action == 'W':
                    new_balance += 1
                elif action == 'L':
                    new_balance -= 1
                # D doesn't change balance

                # For non-final positions, |balance| must be < k
                if i < n - 1:
                    if abs(new_balance) >= k:
                        continue

                new_offset = new_balance + OFFSET

                if not reach[i + 1][new_offset]:
                    reach[i + 1][new_offset] = True
                    parent[i + 1][new_offset] = (prev_offset, action)

    # Final condition: |balance| must equal k at the end
    final_valid = reach[n][OFFSET + k] or reach[n][OFFSET - k]
    if not final_valid:
        return "NO"

    # Backtrack to reconstruct the solution
    result = []
    if reach[n][OFFSET + k]:
        curr_offset = OFFSET + k
    else:
        curr_offset = OFFSET - k

    for i in range(n, 0, -1):
        prev_offset, action = parent[i][curr_offset]
        result.append(action)
        curr_offset = prev_offset

